SELECT question,COUNT(*) n,SUM(fraction) s,SUM(GREATEST(fraction,0)) pos FROM mdl_question_answers WHERE question IN (68854,68855,68856,68857,68858,68859,68860,68861) GROUP BY question;
SELECT q.id,q.name,o.single FROM mdl_question q JOIN mdl_qtype_multichoice_options o ON o.questionid=q.id WHERE q.id IN (68854,68855,68856,68857,68858,68859,68860,68861);
